WITH daily_sales AS ( SELECT d.d_date, d.d_year, i.i_category, i.i_brand, s.s_store_name, hd.hd_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, COUNT(DISTINCT c.c_customer_sk) AS distinct_customers, SUM(COALESCE(ss.ss_ext_sales_price,0) + COALESCE(cs.cs_ext_sales_price,0) + COALESCE(ws.ws_ext_sales_price,0)) AS total_sales, SUM(COALESCE(ss.ss_net_profit,0) + COALESCE(cs.cs_net_profit,0) + COALESCE(ws.ws_net_profit,0)) AS total_profit, SUM(COALESCE(sr.sr_return_amt_inc_tax,0)) AS total_returns FROM date_dim d JOIN store_sales ss ON ss.ss_sold_date_sk = d.d_date_sk JOIN time_dim t ON ss.ss_sold_time_sk = t.t_time_sk JOIN item i ON ss.ss_item_sk = i.i_item_sk JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN customer_address ca ON ss.ss_addr_sk = ca.ca_address_sk JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk LEFT JOIN store_returns sr ON sr.sr_ticket_number = ss.ss_ticket_number AND sr.sr_item_sk = ss.ss_item_sk AND sr.sr_store_sk = s.s_store_sk AND sr.sr_returned_date_sk = d.d_date_sk AND sr.sr_return_time_sk = t.t_time_sk LEFT JOIN catalog_sales cs ON cs.cs_item_sk = i.i_item_sk AND cs.cs_sold_date_sk = d.d_date_sk AND cs.cs_sold_time_sk = t.t_time_sk AND cs.cs_promo_sk = p.p_promo_sk LEFT JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk LEFT JOIN web_sales ws ON ws.ws_item_sk = i.i_item_sk AND ws.ws_sold_date_sk = d.d_date_sk AND ws.ws_sold_time_sk = t.t_time_sk AND ws.ws_promo_sk = p.p_promo_sk LEFT JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk WHERE d.d_year = 2001 AND i.i_current_price > 50 AND p.p_discount_active = 'Y' AND ca.ca_country = 'United States' GROUP BY d.d_date, d.d_year, i.i_category, i.i_brand, s.s_store_name, hd.hd_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound ) SELECT ds.d_year, ds.i_category, ds.s_store_name, SUM(ds.distinct_customers) AS total_distinct_customers, SUM(ds.total_sales) AS total_sales, SUM(ds.total_profit) AS total_profit, SUM(ds.total_returns) AS total_returns, CASE WHEN SUM(ds.total_profit) > 0 THEN 'Profit' ELSE 'Loss' END AS profit_flag, AVG(ds.total_sales) AS avg_daily_sales FROM daily_sales ds GROUP BY ROLLUP(ds.d_year, ds.i_category, ds.s_store_name) HAVING SUM(ds.total_sales) > 1000 ORDER BY ds.d_year, ds.i_category, ds.s_store_name LIMIT 100
